/**
 * verdict-record — the record type of schema id `specstride.verdict/1`, feature 101, data-model.md, "Verdict record".
 *
 * Generated by `scripts/types.mjs` from `schemas/verdict-record.schema.json` (research.md,
 * D-1) — do not edit; re-run the `build` script of the package instead. The
 * fields keep the meaning, the type in words and the required cell of the
 * annex as documentation.
 */
export interface VerdictRecord {
  /**
   * Schema id
   *
   * Type in words: Text.
   */
  schema: string;
  /**
   * Identity of the verdict
   *
   * Type in words: Text.
   */
  verdictId: string;
  /**
   * The phase attempt the verdict belongs to
   *
   * Type in words: Text.
   */
  attemptId: string;
  /**
   * The phase the verdict belongs to
   *
   * Type in words: Whole number.
   */
  phase: number;
  /**
   * The ordinal of the phase attempt the verdict belongs to
   *
   * Type in words: Whole number.
   */
  ordinal: number;
  /**
   * APPROVED, REJECTED or MALFORMED (annex X §X.6 row 8)
   *
   * Type in words: Member of a closed set.
   */
  verdict: "APPROVED" | "REJECTED" | "MALFORMED";
  /**
   * For MALFORMED: a member of the closed set of details (annex X §X.6 row 251). Present only with MALFORMED
   *
   * Type in words: Member of a closed set, or absent.
   */
  detail?: "nonce-mismatch" | "no-verdict-line" | "multiple-verdict-lines" | "call-failed";
  /**
   * The reason line of a verdict that is no approval, at most 120 characters
   *
   * Type in words: Text, or absent.
   */
  reason?: string;
  /**
   * One entry per call of the strategy; at least one entry. The session id of no entry equals a session id of a pass of the phase attempt
   *
   * Type in words: List of records.
   */
  calls: Array<{
    /**
     * Who judged: the harness, the provider, the model, the form of the `completion` level and the proof of that form
     *
     * Type in words: Record.
     */
    critic: {
      /**
       * The harness of the critic
       *
       * Type in words: Text.
       */
      harness: string;
      /**
       * The provider of the critic
       *
       * Type in words: Text.
       */
      provider: string;
      /**
       * The model of the critic
       *
       * Type in words: Text.
       */
      model: string;
      /**
       * The form of the `completion` level the call ran in (annex C §C.3)
       *
       * Type in words: Member of a closed set.
       */
      form: string;
      /**
       * The proof of the form and its result, or null where the profile asks for none
       *
       * Type in words: Record, or null.
       */
      proof: Record<string, unknown> | null;
    };
    /**
     * The session the call ran in; it is never a session of a pass of the phase attempt
     *
     * Type in words: Text.
     */
    sessionId: string;
    /**
     * The hash of the nonce of the call. The nonce itself is never written (F100-FR-139)
     *
     * Type in words: Text.
     */
    nonceHash: string;
    /**
     * When the call was made
     *
     * Type in words: Time.
     */
    at: string;
    /**
     * What the call used, as the harness reported it, or null where it reported nothing
     *
     * Type in words: Record, or null.
     */
    usage: Record<string, unknown> | null;
    /**
     * How long the call took, in milliseconds, or null where it is not known
     *
     * Type in words: Whole number, or null.
     */
    latencyMs: number | null;
    /**
     * How the call ended
     *
     * Type in words: Text.
     */
    outcome: string;
  }>;
  /**
   * The as-is form: the header lines, the prompt in full, and the reply or `(empty)`
   *
   * Type in words: Record.
   */
  transcript: {
    /**
     * The header lines, in order: phase, attempt, provider, nonce, verdict, parse
     *
     * Type in words: List of text.
     */
    header: Array<string>;
    /**
     * The prompt in full, as it was sent
     *
     * Type in words: Text.
     */
    prompt: string;
    /**
     * The reply, or the as-is text `(empty)` where the reply held no bytes
     *
     * Type in words: Text.
     */
    reply: string;
  };
}
